import{_ as r,C as s,o as n,c as l,a3 as i,b as o,w as t,a as u,E as d,a4 as k}from"./chunks/framework.BvvarXmc.js";const m="/screenshots/kantin-dashboard.png",T=JSON.parse('{"title":"Ekosistem Kantin & Koperasi Digital","description":"","frontmatter":{},"headers":[],"relativePath":"panduan-kantin/index.md","filePath":"panduan-kantin/index.md","lastUpdated":null}'),p={name:"panduan-kantin/index.md"};function g(h,a,b,c,D,_){const e=s("Mermaid");return n(),l("div",null,[a[1]||(a[1]=i('<h1 id="ekosistem-kantin-koperasi-digital" tabindex="-1">Ekosistem Kantin &amp; Koperasi Digital <a class="header-anchor" href="#ekosistem-kantin-koperasi-digital" aria-label="Permalink to &quot;Ekosistem Kantin &amp; Koperasi Digital&quot;">​</a></h1><p>Modul <strong>Kantin &amp; Koperasi Sekolah</strong> adalah sistem terpadu untuk mengelola seluruh transaksi jual-beli makanan, minuman, dan perlengkapan siswa di lingkungan sekolah secara digital (<em>cashless</em>).</p><p>Modul ini menghubungkan kasir stan kantin, pengelola koperasi, bendahara sekolah, dan orang tua siswa dalam satu ekosistem transaksi yang aman, cepat, dan transparan.</p><hr><h2 id="tampilan-dashboard-kantin" tabindex="-1">Tampilan Dashboard Kantin <a class="header-anchor" href="#tampilan-dashboard-kantin" aria-label="Permalink to &quot;Tampilan Dashboard Kantin&quot;">​</a></h2><p>Halaman dashboard memberikan gambaran performa penjualan, omset hari ini, item terlaris, serta status stok barang secara langsung (<em>realtime</em>):</p><p><img src="'+m+'" alt="Dashboard Kantin"></p><hr><h2 id="alur-transaksi-non-tunai-cashless-flow" tabindex="-1">Alur Transaksi Non-Tunai (Cashless Flow) <a class="header-anchor" href="#alur-transaksi-non-tunai-cashless-flow" aria-label="Permalink to &quot;Alur Transaksi Non-Tunai (Cashless Flow)&quot;">​</a></h2><p>Diagram alur berikut mengilustrasikan bagaimana transaksi belanja siswa diproses dari awal hingga tutup buku:</p>',10)),(n(),o(k,null,{default:t(()=>[d(e,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%22Siswa%20Membawa%20Kartu%20Pelajar%20RFID%22%5D%20--%3E%20B%5B%22Kasir%20Input%20Item%20Belanja%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22Kasir%20Tap%20Kartu%20Siswa%20di%20Alat%20RFID%22%5D%0A%20%20%20%20C%20--%3E%20D%7B%22Pengecekan%20Saldo%20dan%20Limit%20Harian%22%7D%0A%20%20%20%20D%20--%3E%7CSaldo%20Cukup%7C%20E%5B%22Saldo%20Dompet%20Terpotong%20Realtime%22%5D%0A%20%20%20%20D%20--%3E%7CSaldo%20Tidak%20Cukup%7C%20F%5B%22Peringatan%20Merah%20di%20Layar%20Kasir%22%5D%0A%20%20%20%20E%20--%3E%20G%5B%22Struk%20Kasir%20Dicetak%20via%20Printer%20Thermal%22%5D%0A%20%20%20%20G%20--%3E%20H%5B%22Data%20Masuk%20ke%20Riwayat%20Penjualan%22%5D%0A%20%20%20%20H%20--%3E%20I%5B%22Tutup%20Buku%20Harian%20dan%20Bagi%20Hasil%20Supplier%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[u(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<hr><h2 id="keunggulan-sistem-kantin-digital" tabindex="-1">Keunggulan Sistem Kantin Digital <a class="header-anchor" href="#keunggulan-sistem-kantin-digital" aria-label="Permalink to &quot;Keunggulan Sistem Kantin Digital&quot;">​</a></h2><ol><li><strong>Bebas Antrean Panjang (Quick Checkout)</strong>: Proses pembayaran hanya membutuhkan waktu 2–3 detik per siswa cukup dengan menempelkan kartu pelajar pada sensor RFID, tanpa perlu mencari uang kembalian.</li><li><strong>Perlindungan Uang Saku &amp; Kontrol Orang Tua (Daily Limits)</strong>: Orang tua tidak perlu khawatir uang saku anak hilang atau digunakan berlebihan, karena sistem membatasi batas jajan harian maksimal per hari.</li><li><strong>Pencatatan Konsinyasi &amp; Kemitraan Otomatis</strong>: Makanan yang dititipkan oleh pedagang luar (supplier mitra kantin) otomatis terhitung omsetnya, dipotong komisi kasir sekolah, dan siap dicairkan melalui fitur tutup buku.</li><li><strong>Higienis &amp; Aman</strong>: Mengurangi peredaran uang kertas dan koin di area makanan kantin sekolah, menciptakan lingkungan sekolah yang lebih sehat dan modern.</li></ol><hr><h2 id="daftar-panduan-fitur-di-modul-ini" tabindex="-1">Daftar Panduan Fitur di Modul Ini <a class="header-anchor" href="#daftar-panduan-fitur-di-modul-ini" aria-label="Permalink to &quot;Daftar Panduan Fitur di Modul Ini&quot;">​</a></h2><ol><li><strong><a href="/panduan-kantin/pos-kasir">Kasir POS &amp; Scan Kartu RFID</a></strong>: Panduan lengkap bagi petugas kasir untuk melayani transaksi belanja siswa menggunakan kartu pelajar.</li><li><strong><a href="/panduan-kantin/daftar-menu">Manajemen Menu &amp; Cetak Barcode</a></strong>: Cara mendaftarkan makanan, harga jual, harga pokok (HPP), kontrol stok, dan cetak lembaran barcode menu.</li><li><strong><a href="/panduan-kantin/limit-harian">Batas Belanja Harian Siswa</a></strong>: Pengaturan batas maksimal jajan per hari baik secara global maupun khusus per anak.</li><li><strong><a href="/panduan-kantin/tutup-buku">Tutup Buku &amp; Settlement Supplier</a></strong>: Rekapitulasi omset, pembagian komisi kantin, dan pencairan pembayaran bagi pedagang titip jual.</li><li><strong><a href="/panduan-kantin/topup-saldo">Layanan Top-Up Saldo Siswa</a></strong>: Tata cara pengisian saldo dompet digital kartu siswa menggunakan setoran tunai.</li></ol>',6))])}const S=r(p,[["render",g]]);export{T as __pageData,S as default};
